$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'scripts\collect-system-safe-proof.ps1';$out=Join-Path $env:TEMP 'beadwise-system-safe-proof.json'
try{& $script -OutputPath $out;$r=Get-Content -Raw $out|ConvertFrom-Json;foreach($id in 'C-SYSTEM-003','C-SYSTEM-011','C-SYSTEM-015','C-SYSTEM-016'){if($id -notin @($r.probes.featureId)){throw "missing $id"}};if($r.mutationPolicy -ne 'read-only'){throw 'system proof mutated state'};'PASS: recommendation, event correlation, readiness and accessibility reads ran'}finally{Remove-Item $out -Force -ErrorAction SilentlyContinue}
